    private void guideOptions(){clear();heading.setText(correction.isEmpty()?L10n.text("Guide corrections"):correction);caption.setText(L10n.text("Find the EPG identity and preview upcoming programmes before selecting it."));input=field(L10n.text("Search the guide"));input.setText(guideQuery);row(L10n.text("Find matches"),"",()->{guideQuery=input.getText().toString().trim();guidePage=0;guideOptions();});int offset=(int)(VelaGuideFix.offset(activity,correction)/60);row(L10n.text("Time offset"),(offset>=0?"+":"")+offset+" min",()->guideOffset());row(L10n.text("Use automatic matching"),L10n.text("Remove this channel's correction"),()->layoutChange(()->VelaGuideFix.reset(activity,correction),this::guideOptions));work(signal->VelaGuideFix.candidates(activity,guideQuery,guidePage,signal),v->{List<String> names=(List<String>)v;for(int i=0;i<Math.min(12,names.size());i++){String alias=names.get(i);row(alias,alias.equals(VelaGuideFix.alias(activity,correction))?L10n.text("✓ Selected"):L10n.text("Preview upcoming programmes"),()->guidePreview(alias));}if(guidePage>0)row(L10n.text("‹ Previous"),"",()->{guidePage--;guideOptions();});if(names.size()>12)row(L10n.text("Next ›"),"",()->{guidePage++;guideOptions();});if(names.isEmpty())note(L10n.text("No matches. Open and refresh the guide first, or try another name."));});first();}
    private void guideOffset(){clear();heading.setText(L10n.text("Adjust time"));caption.setText(correction+L10n.text(" · This changes this channel's listings, not your TV's clock."));int offset=(int)(VelaGuideFix.offset(activity,correction)/60);for(int delta:new int[]{-60,-30,-5,5,30,60})row((delta>0?"+":"")+delta+" min","",()->layoutChange(()->VelaGuideFix.set(activity,correction,VelaGuideFix.alias(activity,correction),Math.max(-720,Math.min(840,offset+delta))),this::guideOffset));row(L10n.text("Back"),"",this::guideOptions);first();}
