    private void discover(){caption.setText(L10n.text("Programmes from your channels. Categories appear when provided by the EPG."));row(L10n.text("When"),new String[]{L10n.text("Now"),L10n.text("Tonight"),L10n.text("Next 48 hours")}[discoveryMode],()->{discoveryMode=(discoveryMode+1)%3;discoveryPage=0;render();});row(L10n.text("Type"),new String[]{L10n.text("All"),L10n.text("Movies"),L10n.text("Sports"),L10n.text("Documentaries"),L10n.text("Kids")}[discoveryGenre],()->{discoveryGenre=(discoveryGenre+1)%5;discoveryPage=0;render();});work(signal->host.discover(discoveryMode,discoveryGenre,discoveryPage,signal),v->{List<VelaShows.Airing> raw=(List<VelaShows.Airing>)v;int rawCount=raw.size();Map<String,List<VelaShows.Airing>> grouped=new LinkedHashMap<>();for(VelaShows.Airing p:raw){String key=p.start+"|"+p.end+"|"+(p.eventId.isEmpty()?VelaWorkspace.normal(p.title)+"|"+TvChannelNames.match(p.channel):p.eventId);grouped.computeIfAbsent(key,k->new ArrayList<>()).add(p);}for(List<VelaShows.Airing> group:grouped.values()){VelaShows.Airing p=group.get(0);row(p.title,when(p)+(group.size()>1?"  +"+(group.size()-1):""),()->{if(group.size()==1)airing(p);else{clear();heading.setText(p.title);for(VelaShows.Airing a:group)row(a.channel,when(a),()->airing(a));row(L10n.text("Back"),"",this::render);first();}});}if(grouped.isEmpty())note(L10n.text("No matching broadcasts in the saved guide. Change the filter or refresh Television."));if(discoveryPage>0)row(L10n.text("‹ Previous"),"",()->{discoveryPage--;render();});if(rawCount==24)row(L10n.text("Next ›"),"",()->{discoveryPage++;render();});});}
    boolean remote(KeyEvent event){if(event.getKeyCode()==KeyEvent.KEYCODE_BACK||event.getKeyCode()==KeyEvent.KEYCODE_BUTTON_B||event.getKeyCode()==KeyEvent.KEYCODE_ESCAPE){if(event.getAction()==KeyEvent.ACTION_UP){if(testing){testing=false;capture="";status.setText(t("Test finished.","Prueba terminada."));}else if(layoutDraft!=null){layoutDraft=null;grabbed="";render();}else if(pending!=null){pending=null;render();}else close();}return true;}if(testing){status.setText(KeyEvent.keyCodeToString(event.getKeyCode())+" · "+(event.getAction()==0?"↓":"↑")+" · "+t("device ","dispositivo ")+event.getDeviceId());if(!capture.isEmpty()&&event.getAction()==KeyEvent.ACTION_UP){if(VelaRemote.allowed(event.getKeyCode())){VelaRemote.assign(activity,capture,event.getKeyCode());changed=true;testing=false;capture="";render();status.setText(t("Shortcut saved.","Atajo guardado."));}else status.setText(t("That button is reserved. Choose another, or Back to cancel.","Ese botón está reservado. Elige otro o pulsa Atrás para cancelar."));}return true;}return false;}
    interface Job {Object run(CancellationSignal signal)throws Exception;}
    interface Result {void ready(Object value);}
    private void mutate(Job job,Result result){work(signal->{synchronized(VelaWorkspace.class){signal.throwIfCanceled();return job.run(signal);}},result);}
    private void work(Job job,Result result){cancelWork();int token=epoch;String profile=VelaWorkspace.active(activity);CancellationSignal jobSignal=cancel;task=worker.submit(()->{try{Object value=job.run(jobSignal);if(value instanceof AutoCloseable){disposables.add((AutoCloseable)value);if(closed||jobSignal.isCanceled()){disposables.remove(value);((AutoCloseable)value).close();return;}}main.post(()->{if(value instanceof AutoCloseable)disposables.remove(value);if(!closed&&epoch==token&&profile.equals(VelaWorkspace.active(activity)))result.ready(value);else if(value instanceof AutoCloseable)try{((AutoCloseable)value).close();}catch(Exception ignored){}});}catch(Exception failure){main.post(()->{if(!closed&&epoch==token)status.setText(t("The operation could not be completed. Your accounts are unchanged.","No se pudo completar la operación. Tus cuentas se conservan."));});}});}
    private void cancelWork(){epoch++;cancel.cancel();if(task!=null)task.cancel(true);worker.purge();cancel=new CancellationSignal();}
    void pause(){stopMobile();cancelWork();}
